category.catDesc:
Ambiguità relative alla “sicurtà” mistica e alla percezione
                            dell’impossibilità di peccare nello stato di unione (impeccabilità);
                            richiede continui interventi mitiganti.

teiHeader.xenoData:
{
"pipeline": "TEI-driven and AI-assisted workflow for Castello dell’anima",
"model": {
"primary": "Claude Sonnet 5",
"fallback": "Gemini",
"constraints": {
"historical_style": "XVII-century Italian",
"forbidden": [
"modernisms",
"anachronisms",
"semantic elaborations"
],
"tei_integrity": true
}
},
"operations": {
"remove_citation":    { "code": "-CIT" },
"recover_deletions":  { "code": "+TEXTsub" },
"integrate_citation": { "code": "+CIT", "max_words": 35 }
},
"parameters": {
"temperature": 0.2,
"top_p": 0.95
},
"indicators": {
"clarity_score": "0–1 continuous",
"cohesion_local": "referential chains delta pre/post",
"doctrinal_stability": ["low","medium","high"]
},
"audit_trail": {
"required_fields": [
"locus_id", "operation", "seed",
"prompt_hash", "output_hash",
"reviewer", "esito", "notes"
],
"governance": "expert-in-the-loop"
},
"last_update": "2026-07-25"
}
